return msg;

for ( const [index, command] of msg.result.haConfigQueue.entries() ) {
    var msgMqtt = command
    msgMqtt.delay = index * 5
    node.send([null, msgMqtt, null])
}

var msgOut = {
    settings: msg.settings,
    result: msg.result,
}

return [msg, null, msgOut];

for ( const [index, command] of msg.result.haValueQueue.entries() ) {
    var msgMqtt = command
    msgMqtt.delay = index * 5
    node.send(msgMqtt, null)
}

return [null, msg];

// This function extract data from TTN payload and place it in "metaData" and "sensorData"
//   - decoded data
//   - deviceName
//   - application
//   - join_eui
//   - timestamp
//   - timestamp_hr   (human readable)
//   - rssi   (strongest signal)


// Define the pattern to match the topic
//const pattern = /^v3\/[^\/]+\/devices\/[^\/]+\/up\/[^\/]+/;
const pattern = /^v3\/[^\/]+\/devices\/[^\/]+\/up$/;

// Check if the topic matches the pattern
if (!pattern.test(msg.topic)) {
    msg.info = "no up topic"
    return [msg, null]; // Pass the message if it matches
}

// checks if key excist in obj, Checks on every level in key
function checkKeyInObj(key, obj) {
    if ( typeof obj !== "object" || obj === null ) {
        return false;
    }

    const keys = key.split('.')

    for ( const part of keys ) {
        const match = part.match(/^([^\[\]]+)(?:\[(\d+)\])?$/); // Matches "property" or "property[index]"
        if ( !match ) {
            return { exist: false, value: undefined };
        }

        const property = match[1] // The property name
        const index = match[2]   // The optional array index

        // Ensure `obj` is an object or array and has the property
        if ( typeof obj !== "object" || obj === null || !( property in obj ) ) {
            return { exist: false, value: undefined }
        }
        obj = obj[property] // Move to the next level

        // Handle array indexing
        if (index !== undefined) {
            if ( !Array.isArray(obj) || !( index in obj ) ) {
                return { exist: false, value: undefined }
            }
            obj = obj[index]; // Move to the indexed array element
        }
    }
    return { exist: true, value: obj }
}

function dateConvert(timestamp) {
    const date = new Date(timestamp)
    var day = date.getDate().toString()
    var month = (date.getMonth() + 1).toString()
    var year = date.getFullYear().toString()
    var hour = date.getHours().toString()
    var minutes = date.getMinutes().toString()
